                if type(orig)=="function" then return orig(opts) end
                if type(opts)=="table" and (not opts.Method or opts.Method=="GET") then
                    local ok2,body = pcall(function() return game:HttpGet(url,true) end)
                    if ok2 and body then return {StatusCode=200,Status=200,Body=body} end
                end
                return {StatusCode=0,Status=0,Body=""}
            end
            local u = url:lower()
            local sid="bs-"..tostring(math.random(1e6,9e6))
            local stok="bt-"..tostring(math.random(1e6,9e6))
            local chal=string.rep("61",32)
            local cid="bc-"..tostring(math.random(1e5,9e5))
            local body
            if u:find("access%-mode") or u:find("loader/access") then
                body=J({status="ok",data={mode="public_maintenance"}})
            elseif u:find("check/challenge") then
                body=J({status="ok",transportKey=chal,challengeId=cid})
            elseif u:find("check/maintenance") then
                body=J({status="ok",
                    session={sessionId=sid,sessionToken=stok,
                             nextHeartbeatSeconds=999999,
                             accessTier="premium",licenseType="premium"},
                    continuityCredential="bypass",
                    accessTier="premium",licenseType="premium"})
            elseif u:find("heartbeat") then
                body=J({status="ok",state="active"})
            elseif u:find("/api/v1/check") then
                body=J({status="ok",
                    session={sessionId=sid,sessionToken=stok,
                             nextHeartbeatSeconds=999999,
                             accessTier="premium",licenseType="premium"},
                    continuityCredential="bypass"})
            else
                body=J({status="ok"})
            end
            return {StatusCode=200,Status=200,Body=body}
        end
        rawset(ge, "__FyyFakeReq", fakeReq)
    end

    -- rawset ke semua env agar rawget payload dapat versi hooked
    for _, k in ipairs({"request","http_request","httprequest"}) do
        if rawget(ge, k) ~= nil then rawset(ge, k, fakeReq) end
    end
    if not rawget(ge,"request") and not rawget(ge,"http_request") then
        rawset(ge, "request", fakeReq)
    end
    for _, env in ipairs({root_env, hH45k3O}) do
        if type(env) == "table" then
            for _, k in ipairs({"request","http_request","httprequest"}) do
                if rawget(env,k) ~= nil then rawset(env,k,fakeReq) end
            end
            if not rawget(env,"request") then rawset(env,"request",fakeReq) end
        end
    end

    -- Simpan file bypass key agar auto-load saat rejoin
    pcall(function()
        local wf  = rawget(ge,"writefile")  or rawget(ge,"writeFile")
        local mf  = rawget(ge,"makefolder") or rawget(ge,"makeFolder")
        local isf = rawget(ge,"isfolder")   or rawget(ge,"isFolder")
        if wf then
            if mf then pcall(function()
                if not (isf and isf("FyyCommunity")) then mf("FyyCommunity") end
            end) end
            pcall(wf, "FyyCommunity/license.key", "FYY-BYPASS-KEYLESS")
        end
    end)

    -- INJECTOR: pin request ke fakeReq via rawset
    do
        local _inj_ge = (getgenv and getgenv()) or _G
        local _inj_fake = rawget(_inj_ge, "__FyyFakeReq") or fakeReq
        if _inj_fake then
            rawset(_inj_ge, "request", _inj_fake)
            rawset(_inj_ge, "__FyyFakeReq", _inj_fake)
            if rawget(_inj_ge,"http_request") then rawset(_inj_ge,"http_request",_inj_fake) end
            if rawget(_inj_ge,"httprequest") then rawset(_inj_ge,"httprequest",_inj_fake) end
            warn("[FyyBypass] INJECTOR done — request pinned to fakeReq")
        end
    end
end

local _ok, _ret = pcall(__FYY_PAYLOAD_FN, root_env)
if _ok then
    -- Auto-load monitor setelah payload berhasil
    -- Juga intercept queue_on_teleport agar SELALU persistent (bukan ONE TIME)
    task.delay(3, function()
        pcall(function()
            local _ge_tp = (getgenv and getgenv()) or _G
            local _SAGA_URL2 = "https://cdn.jsdelivr.net/gh/Galangpratama-rox/Decode-SAE@main/SagaHub_OneFile.lua"
            -- SELALU pakai __FyyNativeQot (executor native, bukan wrapper)
            -- Ini mencegah double-wrap yang menyebabkan fail setelah 5-7 hop
            local _native_qot2 = rawget(_ge_tp, "__FyyNativeQot")
            if type(_native_qot2) == "function" then
                -- Reset guard agar hook bisa di-install ulang dengan benar
                rawset(_ge_tp, "__FyyQotHooked", nil)
                rawset(_ge_tp, "queue_on_teleport", function(script_src)
                    warn("[FyyBypass] queue_on_teleport called (post-payload)")
                    local new_script = 'loadstring(game:HttpGet("' .. _SAGA_URL2 .. '", true))()'
                    return _native_qot2(new_script)  -- native, tidak pernah wrap lagi
                end)
                rawset(_ge_tp, "__FyyQotHooked", true)
                warn("[FyyBypass] queue_on_teleport re-hooked via native")
            end
        end)
    end)

    -- Rename "FyyCommunity" -> "SagaHub" di seluruh UI (CoreGui + PlayerGui)
    task.delay(4, function()
        pcall(function()
            local function renameGui(parent)
                for _, obj in ipairs(parent:GetDescendants()) do
                    pcall(function()
                        if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then
                            if obj.Text:find("FyyCommunity") or obj.Text:find("Fyy Community") then
                                obj.Text = obj.Text:gsub("FyyCommunity", "SagaHub"):gsub("Fyy Community", "SagaHub")
                            end
                        end
                        -- Rename ScreenGui / Frame names yang visible
                        if obj:IsA("ScreenGui") or obj:IsA("Frame") then
                            if obj.Name:find("FyyComm") then
                                pcall(function() obj.Name = obj.Name:gsub("FyyCommunity","SagaHub"):gsub("FyyComm","SagaHub") end)
                            end
                        end
                    end)
                end
            end
            -- Scan CoreGui (tempat FyyUI render)
            pcall(function() renameGui(game:GetService("CoreGui")) end)
            -- Scan PlayerGui juga
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                if lp then renameGui(lp:WaitForChild("PlayerGui", 3)) end
            end)
            warn("[SagaHub] UI renamed: FyyCommunity -> SagaHub")
        end)
    end)
    task.delay(6, function()
        pcall(function()
            local _mon_src = game:HttpGet(
                "https://cdn.jsdelivr.net/gh/Galangpratama-rox/Decode-SAE@main/SagaHub_Monitor.lua?v="..tostring(os.time()),
                true
            )
            if _mon_src and #_mon_src > 100 then
                loadstring(_mon_src)()
            end
        end)
    end)
    local StarterGui = game:GetService("StarterGui")
    pcall(function() StarterGui:SetCore("SendNotification", {Title="FyyCommunity ✅", Text="Executor: "..executor, Duration=5}) end)
    return _ret
else
    local StarterGui = game:GetService("StarterGui")
    pcall(function() StarterGui:SetCore("SendNotification", {Title="FyyCommunity ❌", Text="Payload failed — lihat console", Duration=6}) end)
    error("[FyyCommunity OneFile] Payload EXEC FAILED: " .. tostring(_ret))
end